INSERT INTO public.quotes (lang, category, text, author) VALUES
  ('en', 'running', 'To give anything less than your best is to sacrifice the gift.', 'Steve Prefontaine'),
  ('en', 'running', 'I run to see who has the most guts.', 'Steve Prefontaine'),
  ('en', 'running', 'Somebody may beat me, but they are going to have to bleed to do it.', 'Steve Prefontaine'),
  ('en', 'running', 'The best pace is a suicide pace, and today looks like a good day to die.', 'Steve Prefontaine'),
  ('en', 'running', 'When a runner is tired, he runs with his heart.', 'Emil Zatopek'),
  ('en', 'running', 'Great is the victory, but the friendship of all is greater.', 'Emil Zatopek'),
  ('en', 'running', 'Pain is inevitable. Suffering is optional.', 'Haruki Murakami'),
  ('en', 'running', 'The most important thing in the Olympic Games is not to win but to take part.', 'Pierre de Coubertin'),
  ('en', 'running', 'If you have a body, you are an athlete.', 'Bill Bowerman'),
  ('en', 'running', 'There is no such thing as bad weather, only soft people.', 'Bill Bowerman'),
  ('en', 'running', 'Run when you can, walk if you have to, crawl if you must; just never give up.', 'Dean Karnazes'),
  ('en', 'running', 'Somewhere along the line we seem to have confused comfort with happiness.', 'Dean Karnazes'),
  ('en', 'running', 'The body achieves what the mind believes.', 'Jim Evans'),
  ('en', 'running', 'The will to win means nothing without the will to prepare.', 'Juma Ikangaa'),
  ('en', 'running', 'Ask yourself: ''Can I give more?''. The answer is usually: ''Yes''.', 'Paul Tergat'),
  ('en', 'running', 'Long distance running is 90 percent mental and the other half is physical.', 'Rich Davis'),
  ('en', 'running', 'Stadiums are for spectators. We runners have nature and that is much better.', 'Juha Vaatainen'),
  ('en', 'running', 'Running is the classical road to self-consciousness.', 'Roger Bannister'),
  ('en', 'running', 'I don''t run to add days to my life, I run to add life to my days.', 'Ronald Rook'),
  ('en', 'running', 'The marathon is a charismatic event. It has everything.', 'Bill Rodgers'),
  ('en', 'running', 'Running is real and relatively simple, but it ain''t easy.', 'Mark Will-Weber'),
  ('en', 'running', 'The thoughts that occur to me while I''m running are like clouds in the sky.', 'Haruki Murakami'),
  ('en', 'running', 'I run; therefore I am.', 'Bart Yasso'),
  ('en', 'running', 'Never limit where running can take you.', 'Bart Yasso'),
  ('en', 'running', 'Don''t dream of winning, train for it.', 'Mo Farah'),
  ('en', 'running', 'Run the mile you are in.', NULL),
  ('en', 'running', 'Discomfort is the price of admission to a meaningful life.', NULL),
  ('en', 'running', 'The pain you feel today will be the strength you feel tomorrow.', NULL),
  ('en', 'running', 'Slow miles still count.', NULL),
  ('en', 'running', 'Show up. Lace up. Move.', NULL),
  ('en', 'running', 'There is no finish line for an everyday runner.', NULL),
  ('en', 'running', 'One run at a time, one day at a time.', NULL),
  ('en', 'running', 'If it doesn''t challenge you, it doesn''t change you.', NULL),
  ('en', 'running', 'Train hard, finish strong.', NULL),
  ('en', 'running', 'Easy days make hard days possible.', NULL),
  ('en', 'running', 'Listen to your body, but don''t always agree with it.', NULL),
  ('en', 'running', 'The first mile is a liar.', NULL),
  ('en', 'running', 'The second mile is honest.', NULL),
  ('en', 'running', 'Mile three is where you find yourself.', NULL),
  ('en', 'running', 'Sweat is just fat crying — and joy laughing.', NULL),
  ('en', 'running', 'You don''t have to be fast. You just have to start.', NULL),
  ('en', 'running', 'The runner does not stand still.', NULL),
  ('en', 'running', 'Make peace with the pace you have today.', NULL),
  ('en', 'running', 'Pace is a feeling, not a number.', NULL),
  ('en', 'running', 'Trust the long run.', NULL),
  ('en', 'running', 'Recovery is part of training.', NULL),
  ('en', 'running', 'Sleep is the cheapest performance enhancer.', NULL),
  ('en', 'running', 'Hydration is half the workout.', NULL),
  ('en', 'running', 'Form follows fatigue — be kind to your form.', NULL),
  ('en', 'running', 'Cadence cures a lot of problems.', NULL),
  ('en', 'running', 'Run for the love of it, not for the watch.', NULL),
  ('en', 'running', 'The watch lies sometimes — your legs don''t.', NULL),
  ('en', 'running', 'Compete only with the runner you were yesterday.', NULL),
  ('en', 'running', 'There are no shortcuts to anywhere worth going.', NULL),
  ('en', 'running', 'Consistency beats intensity.', NULL),
  ('en', 'running', 'Showing up is the workout.', NULL),
  ('en', 'running', 'Even a bad run is better than no run.', NULL),
  ('en', 'running', 'Some days you fly, some days you drag.', NULL),
  ('en', 'running', 'Running clears the cache.', NULL),
  ('en', 'running', 'Run before you think too much.', NULL),
  ('en', 'running', 'Lace them up before doubt sets in.', NULL),
  ('en', 'running', 'Hills are speedwork in disguise.', NULL),
  ('en', 'running', 'Every hill ends.', NULL),
  ('en', 'running', 'Downhills are gifts; don''t waste them.', NULL),
  ('en', 'running', 'Wind is just resistance training.', NULL),
  ('en', 'running', 'Rain runs make the best stories.', NULL),
  ('en', 'running', 'Running in winter builds character — and patience.', NULL),
  ('en', 'running', 'Run by feel, not by fear.', NULL),
  ('en', 'running', 'Breathe in courage, breathe out doubt.', NULL),
  ('en', 'running', 'Your only opponent is gravity and ego.', NULL),
